<?php $pageTitle='Live Tables'; require_once __DIR__.'/includes/header.php'; require_once __DIR__.'/includes/table-card.php'; $db=getDB(); $q=$db->prepare("SELECT t.*,rp.plan_name,rp.rate_per_minute, s.id session_id,s.player_name_walkin,s.start_time,s.total_pause_seconds,s.billing_type,s.cafe_amount,p.name player_name FROM tables t LEFT JOIN rate_plans rp ON rp.id=t.rate_plan_id LEFT JOIN sessions s ON s.table_id=t.id AND s.status IN ('running','paused','held') LEFT JOIN players p ON p.id=s.player_id WHERE t.club_id=? AND t.is_active=1 ORDER BY t.table_number");$q->execute([$_SESSION['club_id']]);$tables=$q->fetchAll(); ?>
<main class="pt-20 min-h-screen"><div class="p-4 lg:p-6"><div class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-bold"><i class="fa-solid fa-table-cells-large text-green-400 mr-2"></i>Live Tables</h1><p class="text-sm text-slate-400 mt-1">Tap any available table to open a new session.</p></div><div id="floor-stats" class="text-sm text-slate-300"></div></div><section class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 mt-5" id="table-grid"><?php foreach($tables as $table)renderTableCard($table);?></section></div></main><div id="modal-root"></div><script src="<?=url('assets/js/toast.js')?>"></script><script src="<?=url('assets/js/timer.js')?>"></script></body></html>
